// src/components/AdminStudentsFees.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faTrash } from "@fortawesome/free-solid-svg-icons";
import "../styles/main.css";

export default function AdminStudentsFees() {
  const [students, setStudents] = useState([]);
  const [selected, setSelected] = useState(null);
  const [overrides, setOverrides] = useState({});
  const [total, setTotal] = useState(0);
  const [paid, setPaid] = useState(0);
  const [remaining, setRemaining] = useState(0);

  // ------------------------------
  // CLASS-BASED BASE FEE TYPES
  // ------------------------------
  const getBaseFeeKeys = (cls) => {
    const c = Number(cls);

    if (c >= 1 && c <= 5)
      return ["development", "transport"];

    if (c >= 6 && c <= 9)
      return ["tuition", "development", "transport"];

    return ["exam", "tuition", "development"];
  };

  // ------------------------------
  // Fetch all students
  // ------------------------------
  const fetchStudents = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/fees/admin/students");
      setStudents(res.data.data || []);
    } catch (err) {
      console.error(err);
      toast.error("Failed to load students");
    }
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  // ------------------------------
  // Load fee structure for selected student
  // ------------------------------
  const selectStudent = async (stu) => {
    setSelected(stu);

    try {
      const res = await axios.get(
        `http://localhost:5000/api/fees/student/${stu.admissionNo}`
      );

      if (!res.data.success) return toast.error("Failed to load fee");

      const fullFeeObj = res.data.data.fee.items || {};
      const feeOverrides = res.data.data.feeOverrides || {};
      const studentClass = stu.classApplied || stu.class;

      const baseKeys = getBaseFeeKeys(studentClass);

      // 1️⃣ Base fees only
      const filtered = {};
      baseKeys.forEach((key) => {
        filtered[key] = fullFeeObj[key]?.amount || 0;
      });

      // 2️⃣ Add admin-added fee types
      Object.entries(feeOverrides).forEach(([key, value]) => {
        filtered[key] = value;
      });

      setOverrides(filtered);

      // Compute totals
      const paidAmt =
        res.data.data.payments?.reduce((s, t) => s + (t.amount || 0), 0) || 0;
      const totalAmt = Object.values(filtered).reduce((s, v) => s + (v || 0), 0);

      setPaid(paidAmt);
      setTotal(totalAmt);
      setRemaining(Math.max(0, totalAmt - paidAmt));
    } catch (err) {
      console.error(err);
      toast.error("Error loading student fee");
    }
  };

  // ------------------------------
  // Utility to recalc totals
  // ------------------------------
  const recalcTotals = (ovr) => {
    const t = Object.values(ovr).reduce((s, v) => s + (v || 0), 0);
    setTotal(t);
    setRemaining(Math.max(0, t - paid));
  };

  // ------------------------------
  // Admin updates amount
  // ------------------------------
  const updateOverride = (key, value) => {
    const num = Number(value) || 0;

    setOverrides((prev) => {
      const updated = { ...prev, [key]: num };
      recalcTotals(updated);
      return updated;
    });
  };

  // ------------------------------
  // Admin adds new fee type
  // ------------------------------
  const addFeeType = () => {
    const key = prompt("Enter new fee type (e.g. 'dance'):");

    if (!key) return;

    setOverrides((prev) => {
      if (prev[key]) {
        toast.error("Fee type already exists!");
        return prev;
      }
      const updated = { ...prev, [key]: 0 };
      recalcTotals(updated);
      return updated;
    });
  };

  // ------------------------------
  // Admin can delete EXTRA fee types only
  // ------------------------------
  const deleteFeeType = (key) => {
    const baseKeys = getBaseFeeKeys(selected.classApplied || selected.class);

    if (baseKeys.includes(key)) {
      return toast.error("Cannot delete class-based default fee type.");
    }

    setOverrides((prev) => {
      const updated = { ...prev };
      delete updated[key];
      recalcTotals(updated);
      return updated;
    });
  };

  // ------------------------------
  // Save fee overrides to server
  // ------------------------------
  const saveChanges = async () => {
    try {
      const res = await axios.post("http://localhost:5000/api/fees/student", {
        admissionNo: selected.admissionNo,
        feeOverrides: overrides,
      });

      if (res.data.success) {
        toast.success("Fee updated successfully!");
      } else {
        toast.error("Failed to update");
      }
    } catch (err) {
      console.error(err);
      toast.error("Save failed");
    }
  };

  // ------------------------------
  // Reset to server values
  // ------------------------------
  const resetToServerValues = () => {
    if (!selected) return;
    selectStudent(selected);
  };

  return (
    <div className="admin-fees-page">
      <Toaster />

      <h2 style={{ color: "#003366", fontSize: "28px", marginBottom: "10px" }}>
        Manage Student Fees
      </h2>

      <div className="admin-fee-grid">
        {/* -----------------------------
            Student List
        ------------------------------ */}
        <div className="student-list">
          <h3 style={{ color: "#003366" }}>All Students</h3>

          {students.length === 0 && <p>No students found.</p>}

          <ul>
            {students.map((stu) => (
              <li
                key={stu._id}
                onClick={() => selectStudent(stu)}
                className={selected?._id === stu._id ? "selected" : ""}
              >
                <b>{stu.studentName}</b> ({stu.admissionNo})
              </li>
            ))}
          </ul>
        </div>

        {/* -----------------------------
            Fee Editor
        ------------------------------ */}
        <div className="fee-editor">
          {!selected ? (
            <p>Select a student to edit fees.</p>
          ) : (
            <>
              <h3 style={{ color: "#003366" }}>
                Edit Fees — {selected.studentName} (Class {selected.classApplied || selected.class})
              </h3>

              <button onClick={addFeeType} style={{ marginRight: 10 }}>
                + Add Fee Type
              </button>

              <button onClick={resetToServerValues}>
                Reset to server values
              </button>

              <table className="fee-table">
                <thead>
                  <tr>
                    <th>Fee Type</th>
                    <th>Amount (₹)</th>
                  </tr>
                </thead>

                <tbody>
                  {Object.entries(overrides).map(([key, value]) => (
                    <tr key={key}>
                      <td>
                        {key}

                        {!getBaseFeeKeys(selected.classApplied || selected.class).includes(key) && (
                          <span
                            style={{
                              marginLeft: 10,
                              color: "red",
                              cursor: "pointer",
                            }}
                            title="Delete extra fee type"
                            onClick={() => deleteFeeType(key)}
                          >
                            <FontAwesomeIcon icon={faTrash} />
                          </span>
                        )}
                      </td>

                      <td>
                        <input
                          type="number"
                          value={value}
                          onChange={(e) => updateOverride(key, e.target.value)}
                        />
                      </td>
                    </tr>
                  ))}

                  <tr className="fee-total">
                    <td><b>Total</b></td>
                    <td><b>₹{total.toLocaleString()}</b></td>
                  </tr>

                  <tr>
                    <td>Paid</td>
                    <td>₹{paid.toLocaleString()}</td>
                  </tr>

                  <tr>
                    <td>Remaining</td>
                    <td>₹{remaining.toLocaleString()}</td>
                  </tr>
                </tbody>
              </table>

              <button
                onClick={saveChanges}
                className="ad-stu-fee-save-btn"
                style={{ marginTop: 15 }}
              >
                Save Changes
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
